diff --git a/src/main/java/person/DocumentPolicy.java b/src/main/java/person/DocumentPolicy.java
index d959ab2..99a4204 100644
--- a/src/main/java/person/DocumentPolicy.java
+++ b/src/main/java/person/DocumentPolicy.java
@@ -9,7 +9,7 @@ public final class DocumentPolicy {
     private DocumentPolicy() {}
     public static boolean eligible(Document d, LocalDate asOf) {
         return d.active()
-            && true
+            && !d.annulled()
             && !d.effectiveFrom().isAfter(asOf)
             && (d.expiresOn() == null || !d.expiresOn().isBefore(asOf))
             && d.name().complete();
@@ -17,7 +17,8 @@ public final class DocumentPolicy {
     public static Document choose(List<Document> documents, LocalDate asOf) {
         return documents.stream()
             .filter(d -> eligible(d, asOf))
-            .max(Comparator.comparing(Document::effectiveFrom).thenComparingLong(Document::id))
+            .max(Comparator.comparing(Document::effectiveFrom).reversed()
+                .thenComparingLong(Document::id).reversed())
             .orElse(null);
     }
 }

